import { useMemo } from 'react';

import { Heading } from '@hexa-ui/components';
import { Icon } from '@hexa-ui/components2';
import { Info } from '@hexa-ui/icons2';
import { BreadcrumbChips, CustomTooltip } from 'components';
import { StyledMainContainer } from 'components/ContentCard/ContentCard.styles';
import { usePageFilterApplied } from 'hooks';
import { UseBffDataResponse } from 'hooks/useBffData/useBffData';
import { useStickyNavigationTopOffsetContext } from 'hooks/useStickyNavigationTopOffset';
import { useDrillDownBreadcrumb } from 'pages/pillars/ValueCreation/hooks/useDrillDownBreadcrumb';
import { WaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config';
import {
  LineBarChartsSectionData,
  WaterfallSectionData,
} from 'pages/pillars/ValueCreation/PerformanceTool/types';
import { StyledTooltip } from 'shared/Styles';
import { isMarketShareKpi } from 'utils';

import {
  MARKET_SHARE_COUNTRIES_WITHOUT_BRAND_DATA,
  PERFORMANCE_TOOL_PAGE_NAME,
} from '../../../constants';
import { PERFORMANCE_TOOL_BREADCRUMB_CONFIG } from '../../../constants/breadcrumbConfig';
import { LineBarChartsSection, WaterfallSection } from '../Charts';
import { DriversSection } from '../DriversSection';
import { EmptyBrandContributionSection } from '../EmptyBrandContributionSection';
import { BigNumbersSection } from '../OvertimePerformance/BigNumbersSection/BigNumbersSection';
import {
  StyledPerformanceSectionHeader,
  StyledPerformanceSectionHeaderTopRow,
  StyledSectionsContainer,
} from './PerformanceSection.styles';
import { PerformanceSectionBigNumbersProps } from './types';

export interface PerformanceSectionProps {
  tooltip?: string;
  measure: string;
  lineBarChartsData?: LineBarChartsSectionData;
  waterfallData?: WaterfallSectionData;
  lineBarChartsRequest: UseBffDataResponse;
  waterfallRequest: UseBffDataResponse;
  error?: Error | null;
  waterfallVariant?: 'large' | 'small';
  showDrivers?: boolean;
  waterfallConfig: WaterfallConfig;
  showLineDataLabels?: boolean;
  stickyHeader?: boolean;
  bigNumbersProps?: PerformanceSectionBigNumbersProps;
}

const PERFORMANCE_TOOL_KPIS = {
  power: 'Brand Power',
  volume: 'Volume',
  nr: 'Net Revenue',
  market_share: 'Market Share',
  cores: 'CORES',
};

export const PerformanceSection: React.FC<PerformanceSectionProps> = ({
  tooltip,
  measure,
  lineBarChartsData,
  waterfallData,
  lineBarChartsRequest,
  waterfallRequest,
  waterfallVariant = 'large',
  showDrivers = false,
  waterfallConfig,
  showLineDataLabels = true,
  stickyHeader = true,
  bigNumbersProps,
}) => {
  const stickyTopOffset = useStickyNavigationTopOffsetContext();
  const { applied } = usePageFilterApplied(PERFORMANCE_TOOL_PAGE_NAME);

  const kpi = useMemo(() => {
    return applied.kpis as keyof typeof PERFORMANCE_TOOL_KPIS;
  }, [applied.kpis]);

  const title = useMemo(() => {
    if (kpi) return `${PERFORMANCE_TOOL_KPIS[kpi]} Performance`;
    return `Performance`;
  }, [kpi]);

  const lineBarChartsTitle = useMemo(() => {
    if (kpi) return `${PERFORMANCE_TOOL_KPIS[kpi]} Overtime`;
    return `Overtime`;
  }, [kpi]);

  const waterfallTitle = useMemo(() => {
    if (kpi) return `${PERFORMANCE_TOOL_KPIS[kpi]} Breakdown`;
    return `Breakdown`;
  }, [kpi]);

  const isCountryWithoutBrandData = useMemo(() => {
    return (
      isMarketShareKpi(kpi) &&
      MARKET_SHARE_COUNTRIES_WITHOUT_BRAND_DATA.includes(
        applied?.country as string,
      )
    );
  }, [kpi, applied?.country]);

  const showBreadcrumb = !isCountryWithoutBrandData;
  const {
    rootLabel,
    path,
    goToStep,
    isLoading: isBreadcrumbLoading,
  } = useDrillDownBreadcrumb(PERFORMANCE_TOOL_BREADCRUMB_CONFIG);
  const lineBarChartsSection = (
    <LineBarChartsSection
      title={lineBarChartsTitle}
      measure={measure}
      data={lineBarChartsData}
      loading={lineBarChartsRequest.loading}
      error={lineBarChartsRequest.error}
      showLineDataLabels={showLineDataLabels}
    />
  );

  const waterfallChartsSection = (
    <>
      {showDrivers && !isCountryWithoutBrandData && (
        <DriversSection title={waterfallTitle} measure={measure} />
      )}

      {!showDrivers && !isCountryWithoutBrandData && (
        <WaterfallSection
          config={waterfallConfig}
          title={waterfallTitle}
          measure={measure}
          data={waterfallData}
          variant={waterfallVariant}
          loading={waterfallRequest.loading}
          error={waterfallRequest.error}
        />
      )}

      {isCountryWithoutBrandData && (
        <EmptyBrandContributionSection title={waterfallTitle} />
      )}
    </>
  );

  return (
    <StyledMainContainer fullWidth data-testid="performance-section">
      <StyledPerformanceSectionHeader
        stickyHeader={stickyHeader}
        stickyTopOffset={stickyTopOffset}
        data-testid="performance-section-header"
      >
        <StyledPerformanceSectionHeaderTopRow>
          <Heading size="H3" data-testid="performance-section-title">
            {title}
          </Heading>
          {tooltip && (
            <CustomTooltip
              data-testid="performance-section-tooltip"
              content={<StyledTooltip size="small">{tooltip}</StyledTooltip>}
            >
              <Icon icon={Info} size="medium" />
            </CustomTooltip>
          )}
        </StyledPerformanceSectionHeaderTopRow>
        {showBreadcrumb && (
          <BreadcrumbChips
            path={path}
            rootLabel={rootLabel}
            onGoToStep={goToStep}
            isLoading={isBreadcrumbLoading}
            dataTestId="performance-section-breadcrumb"
          />
        )}
      </StyledPerformanceSectionHeader>
      <StyledSectionsContainer>
        <BigNumbersSection
          variant="embedded"
          title={bigNumbersProps?.title ?? 'Overtime Performance'}
          tooltip={bigNumbersProps?.tooltip}
          data={bigNumbersProps?.data}
          loading={bigNumbersProps?.loading ?? false}
          error={bigNumbersProps?.error ?? null}
          skeletonProps={bigNumbersProps?.skeletonProps}
          onSelect={bigNumbersProps?.onSelect}
          defaultSelected={bigNumbersProps?.defaultSelected ?? 0}
        />
        {isMarketShareKpi(kpi) ? (
          <>
            {lineBarChartsSection}
            {waterfallChartsSection}
          </>
        ) : (
          <>
            {waterfallChartsSection}
            {lineBarChartsSection}
          </>
        )}
      </StyledSectionsContainer>
    </StyledMainContainer>
  );
};
